import React, { useState } from 'react'
import { useAuth } from '../../../contexts/AuthContext'
import { LogIn, Eye } from 'lucide-react'
import { SimpleAuth } from '../../auth/SimpleAuth'

interface LoginButtonProps {
  compact?: boolean
}

const LoginButton: React.FC<LoginButtonProps> = ({ compact = false }) => {
  const { user, loading, isDevMode, signIn } = useAuth()
  const [showAuth, setShowAuth] = useState(false)

  // すでにログイン済みの場合は何も表示しない
  if (user && !loading) {
    return null
  }

  const handleLogin = async (userId: string, username: string) => {
    await signIn(userId, username)
    setShowAuth(false)
  }

  // ヘッダー用のコンパクトボタン
  if (compact) {
    return (
      <>
        <button
          onClick={() => setShowAuth(true)}
          disabled={loading}
          className="flex items-center gap-2 px-4 py-2 text-sm bg-emerald-600 hover:bg-emerald-700 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded-md font-medium transition-colors"
        >
          {loading ? (
            <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white" />
          ) : (
            <LogIn className="h-4 w-4" />
          )}
          {loading ? '...' : 'ログイン'}
        </button>

        {showAuth && (
          <SimpleAuth
            onClose={() => setShowAuth(false)}
            onLogin={handleLogin}
          />
        )}
      </>
    )
  }

  // フルページレイアウト（元の実装）
  return (
    <>
      <div className="flex flex-col items-center justify-center min-h-[60vh] px-4">
        <div className="max-w-md mx-auto text-center space-y-6">
          <div className="space-y-4">
            {isDevMode && (
              <div className="bg-yellow-100 border border-yellow-400 text-yellow-700 px-4 py-3 rounded relative">
                <div className="flex items-center gap-2">
                  <span>🔧</span>
                  <span className="font-medium">開発モード</span>
                </div>
                <p className="text-sm mt-1">Supabase設定なしでUIを確認できます</p>
              </div>
            )}
            <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
              美辞学ナビ
            </h1>
            <p className="text-lg text-gray-600 dark:text-gray-300">
              美辞学ツアーの会場情報をチェックしよう 🎵
            </p>
            <div className="text-sm text-gray-500 dark:text-gray-400 space-y-2">
              <p>🏛️ 会場情報・アクセス・駐車場をチェック</p>
              <p>🗺️ 会場周辺の観光スポット・グルメ情報</p>
              <p>👥 参加表明者の情報も確認できる</p>
            </div>
          </div>
          
          <div className="space-y-3">
            <button
              onClick={() => setShowAuth(true)}
              disabled={loading}
              className="w-full flex items-center justify-center gap-3 px-6 py-3 bg-emerald-600 hover:bg-emerald-700 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded-lg font-medium transition-colors"
            >
              {loading ? (
                <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white" />
              ) : (
                <LogIn className="h-5 w-5" />
              )}
              {loading ? 'ログイン中...' : isDevMode ? '🔧 開発モードでログイン' : 'ログイン・新規登録'}
            </button>
            
            <p className="text-xs text-gray-400 dark:text-gray-500">
              ※ 閲覧のみならログイン不要です
            </p>
          </div>
          
          <div className="text-xs text-gray-400 dark:text-gray-500">
            <p>簡単なユーザーIDでログイン。</p>
            <p>メールアドレスは不要です。</p>
          </div>
        </div>
      </div>

      {showAuth && (
        <SimpleAuth
          onClose={() => setShowAuth(false)}
          onLogin={handleLogin}
        />
      )}
    </>
  )
}

export default LoginButton